test("credit weighted average rounds 3.125 half even to 3.12", function () {
  assert.deepEqual(code.calculateGpa({courses:[{gradePoints:"3.7",credits:"3"},{gradePoints:"3.3",credits:"3"},{gradePoints:"2.0",credits:"2"}]}), {gpa:"3.12"});
});
test("exact decimal rounds 2.675 half even to 2.68 not a float 2.67", function () {
  assert.deepEqual(code.calculateGpa({courses:[{gradePoints:"4.0",credits:"1"},{gradePoints:"3.0",credits:"1"},{gradePoints:"2.0",credits:"1"},{gradePoints:"1.7",credits:"1"}]}), {gpa:"2.68"});
});
test("empty course list returns no gpa and does not error", function () {
  assert.deepEqual(code.calculateGpa({courses:[]}), {gpa:null});
});
test("courses whose credits sum to zero return no gpa not 0.00", function () {
  assert.deepEqual(code.calculateGpa({courses:[{gradePoints:"4.0",credits:"0"},{gradePoints:"3.0",credits:"0"}]}), {gpa:null});
});
test("single course rounds 2 over 3 to 0.67 not by truncation", function () {
  assert.deepEqual(code.calculateGpa({courses:[{gradePoints:"2",credits:"3"}]}), {gpa:"0.67"});
});
test("3.1249 just below the even tie rounds to 3.12", function () {
  assert.deepEqual(code.calculateGpa({courses:[{gradePoints:"3.1249",credits:"1"}]}), {gpa:"3.12"});
});
test("3.1251 just above the even tie rounds to 3.13", function () {
  assert.deepEqual(code.calculateGpa({courses:[{gradePoints:"3.1251",credits:"1"}]}), {gpa:"3.13"});
});
test("2.6749 just below the odd tie rounds to 2.67", function () {
  assert.deepEqual(code.calculateGpa({courses:[{gradePoints:"2.6749",credits:"1"}]}), {gpa:"2.67"});
});
test("2.6751 just above the odd tie rounds to 2.68", function () {
  assert.deepEqual(code.calculateGpa({courses:[{gradePoints:"2.6751",credits:"1"}]}), {gpa:"2.68"});
});
test("rounds only the final quotient so 3.335 becomes 3.34", function () {
  assert.deepEqual(code.calculateGpa({courses:[{gradePoints:"3.335",credits:"3"}]}), {gpa:"3.34"});
});
test("zero grade points with credits returns gpa 0.00 not null", function () {
  assert.deepEqual(code.calculateGpa({courses:[{gradePoints:"0",credits:"1"},{gradePoints:"0.0",credits:"2"}]}), {gpa:"0.00"});
});
test("unknown field on the input object throws unknown field extra", function () {
  assert.throws(function () {
    code.calculateGpa({courses:[{gradePoints:"4",credits:"1"}],extra:"x"});
  }, /^unknown field: extra$/);
});
test("unknown field on the first course throws unknown field note", function () {
  assert.throws(function () {
    code.calculateGpa({courses:[{gradePoints:"4.0",credits:"1",note:"a"},{gradePoints:"3.0",credits:"1"},{gradePoints:"2.0",credits:"1"}]});
  }, /^unknown field: note$/);
});
test("unknown field on the middle course throws unknown field note", function () {
  assert.throws(function () {
    code.calculateGpa({courses:[{gradePoints:"4.0",credits:"1"},{gradePoints:"3.0",credits:"1",note:"b"},{gradePoints:"2.0",credits:"1"}]});
  }, /^unknown field: note$/);
});
test("unknown field on the last course throws unknown field note", function () {
  assert.throws(function () {
    code.calculateGpa({courses:[{gradePoints:"4.0",credits:"1"},{gradePoints:"3.0",credits:"1"},{gradePoints:"2.0",credits:"1",note:"c"}]});
  }, /^unknown field: note$/);
});
test("a number grade points value throws invalid decimal gradePoints", function () {
  assert.throws(function () {
    code.calculateGpa({courses:[{gradePoints:"4.0",credits:"1"},{gradePoints:2.675,credits:"1"},{gradePoints:"3.0",credits:"1"}]});
  }, /^invalid decimal: gradePoints$/);
});
